files.content:
:root {
  --color-bg: #1e1e2f;
  --color-card: #2a2a40;
  --color-primary: #6c63ff;
  --color-primary-hover: #5a52d5;
  --color-accent: #ff6584;
  --color-text: #f0f0f5;
  --color-text-muted: #a0a0b8;
  --color-border: #3d3d5c;
  --color-input-bg: #1e1e2f;
  --font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  --font-size-base: 16px;
  --radius: 12px;
  --spacing: 1.5rem;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

[hidden] {
  display: none !important;
}

body {
  font-family: var(--font-family);
  font-size: var(--font-size-base);
  background-color: var(--color-bg);
  color: var(--color-text);
  min-height: 100vh;
  display: flex;
  justify-content: center;
  align-items: flex-start;
  padding: var(--spacing);
  line-height: 1.5;
}

.card {
  background-color: var(--color-card);
  border-radius: var(--radius);
  padding: var(--spacing);
  width: 100%;
  max-width: 720px;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.3);
}

h1 {
  font-size: 1.75rem;
  font-weight: 700;
  margin-bottom: 0.25rem;
  color: var(--color-primary);
}

.subtitle {
  color: var(--color-text-muted);
  margin-bottom: var(--spacing);
  font-size: 1rem;
}

.visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

#line-items-container {
  display: flex;
  flex-direction: column;
  gap: 1rem;
  margin-bottom: 1rem;
}

.line-item {
  display: flex;
  align-items: flex-end;
  gap: 0.75rem;
  background-color: var(--color-input-bg);
  border: 1px solid var(--color-border);
  border-radius: var(--radius);
  padding: 0.75rem;
}

.line-item-fields {
  display: flex;
  flex-wrap: wrap;
  gap: 0.75rem;
  flex: 1;
}

.field {
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
  flex: 1 1 100%;
}

.field-small {
  flex: 1 1 0;
  min-width: 80px;
}

.field-label {
  font-size: 0.875rem;
  color: var(--color-text-muted);
  font-weight: 600;
}

input[type="text"],
input[type="number"] {
  font-family: inherit;
  font-size: 1rem;
  padding: 0.5rem 0.75rem;
  border-radius: 8px;
  border: 1px solid var(--color-border);
  background-color: var(--color-card);
  color: var(--color-text);
  width: 100%;
  transition: border-color 0.15s, box-shadow 0.15s;
}

input:hover {
  border-color: var(--color-primary);
}

input:focus {
  outline: none;
  border-color: var(--color-primary);
  box-shadow: 0 0 0 3px rgba(108, 99, 255, 0.3);
}

input:active {
  border-color: var(--color-primary-hover);
}

.item-total {
  font-size: 1rem;
  padding: 0.5rem 0.75rem;
  background-color: var(--color-card);
  border-radius: 8px;
  border: 1px solid var(--color-border);
  text-align: right;
  font-variant-numeric: tabular-nums;
  color: var(--color-text);
  display: block;
}

.btn {
  font-family: inherit;
  font-size: 1rem;
  font-weight: 600;
  padding: 0.6rem 1.2rem;
  border-radius: 8px;
  border: none;
  cursor: pointer;
  transition: background-color 0.15s, transform 0.1s;
}

.btn:focus {
  outline: none;
  box-shadow: 0 0 0 3px rgba(108, 99, 255, 0.5);
}

.btn:active {
  transform: scale(0.97);
}

.btn-secondary {
  background-color: var(--color-primary);
  color: #fff;
}

.btn-secondary:hover {
  background-color: var(--color-primary-hover);
}

.btn-remove {
  background-color: transparent;
  color: var(--color-accent);
  font-size: 1.5rem;
  line-height: 1;
  padding: 0.25rem 0.5rem;
  border-radius: 6px;
  flex-shrink: 0;
  align-self: center;
}

.btn-remove:hover {
  background-color: rgba(255, 101, 132, 0.15);
}

.btn-remove:focus {
  box-shadow: 0 0 0 3px rgba(255, 101, 132, 0.5);
}

#totals-section {
  margin-top: var(--spacing);
  border-top: 1px solid var(--color-border);
  padding-top: var(--spacing);
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

.totals-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 1rem;
}

.totals-label {
  font-weight: 600;
  color: var(--color-text-muted);
}

.totals-value {
  font-variant-numeric: tabular-nums;
  font-weight: 600;
}

.tax-input {
  width: 100px;
  text-align: right;
}

.grand-total {
  font-size: 1.25rem;
  border-top: 1px solid var(--color-border);
  padding-top: 0.75rem;
  margin-top: 0.25rem;
}

.grand-total .totals-label {
  color: var(--color-text);
}

.grand-total .totals-value {
  color: var(--color-primary);
}

.empty-message {
  text-align: center;
  color: var(--color-text-muted);
  padding: 1rem 0;
  font-style: italic;
}

@media (max-width: 480px) {
  :root {
    --spacing: 1rem;
  }
  .line-item {
    flex-direction: column;
    align-items: stretch;
  }
  .btn-remove {
    align-self: flex-end;
  }
  .field-small {
    flex: 1 1 100%;
  }
  .tax-input {
    width: 80px;
  }
}

(function () {
  'use strict';

  const container = document.getElementById('line-items-container');
  const addBtn = document.getElementById('add-line-item');
  const taxInput = document.getElementById('tax-rate');
  const subtotalEl = document.getElementById('subtotal');
  const taxAmountEl = document.getElementById('tax-amount');
  const grandTotalEl = document.getElementById('grand-total');
  const emptyMsg = document.getElementById('empty-message');
  const template = document.getElementById('line-item-template');

  function formatCurrency(value) {
    return '$' + value.toFixed(2);
  }

  function parseNumber(value) {
    const n = parseFloat(value);
    return isNaN(n) || n < 0 ? 0 : n;
  }

  function updateTotals() {
    let subtotal = 0;
    const items = container.querySelectorAll('.line-item');
    items.forEach(function (item) {
      const qty = parseNumber(item.querySelector('.item-quantity').value);
      const price = parseNumber(item.querySelector('.item-price').value);
      const lineTotal = qty * price;
      item.querySelector('.item-total').textContent = formatCurrency(lineTotal);
      subtotal += lineTotal;
    });

    const taxRate = parseNumber(taxInput.value);
    const taxAmount = subtotal * (taxRate / 100);
    const grandTotal = subtotal + taxAmount;

    subtotalEl.textContent = formatCurrency(subtotal);
    taxAmountEl.textContent = formatCurrency(taxAmount);
    grandTotalEl.textContent = formatCurrency(grandTotal);

    emptyMsg.hidden = items.length > 0;
  }

  function addLineItem() {
    const clone = template.content.cloneNode(true);
    const lineItem = clone.querySelector('.line-item');
    const removeBtn = clone.querySelector('.btn-remove');

    lineItem.querySelectorAll('input').forEach(function (input) {
      input.addEventListener('input', updateTotals);
    });

    removeBtn.addEventListener('click', function () {
      lineItem.remove();
      updateTotals();
    });

    container.appendChild(clone);
    updateTotals();
    lineItem.querySelector('.item-description').focus();
  }

  addBtn.addEventListener('click', addLineItem);
  taxInput.addEventListener('input', updateTotals);

  // Initialize with one line item
  addLineItem();
})();
